+			}
+			if parts[0] == "" {
+				return nil, errors.New("devices must have a non-empty IDType")
+			}
+			opts = append(opts, oci.WithWindowsDevice(parts[0], parts[1]))
+		}
 	}

 	runtime := context.String("runtime")

body:
Update to the latest version that contains a fix for CVE-2022-27664;
https://github.com/golang/net/commit/f3363e06e74cdc304618bf31d898b78590103527

Signed-off-by: Sebastiaan van Stijn <github@gone.nl>

